{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "The first group is children with an active individualized education program (IEP) who have one of these disabilities as a primary or secondary disability: autism, deaf-blindness, hearing impairments, intellectual disability, orthopedic impairments, traumatic brain injury, visual impairments, developmental delay, multiple disabilities, a specific learning disability, or deafness. The IEP must be in effect when the department receives the request to participate.",
      "rationale": "Conveys the disability list, active IEP requirement, primary-or-secondary designation, and timing, but omits Tennessee residency for this route and the governing state-board disability definitions and IEP standards."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The student must also meet one of three conditions. The student was enrolled in and attended a Tennessee public school for the full prior school year. Or the student is enrolling in a Tennessee school for the first time. Or the student received an IEA in the previous school year.",
      "rationale": "Conveys all three alternative enrollment/history conditions for the disability-based route."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The second group is Tennessee resident children who have a medical condition that keeps them from attending school in person, as determined by the state board of education, and who are entitled to attend public school.",
      "rationale": "Identifies a separate eligibility route with residency, a board-determined medical condition affecting in-person attendance, and public-school entitlement, without imposing the first route's conditions."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "It would still include a nonpublic school that meets the program's requirements and seeks to enroll eligible students. For students in the medical-condition group, it would also include a home school as defined in a cited statute.",
      "rationale": "Conveys both participating-school categories and limits home-school inclusion to medical-condition students."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "A new subsection says the existing section 49-10-1404 does not apply to medical-condition students or to home schools.",
      "rationale": "Identifies the exempted section and both exempt categories, with participating home schools established by the preceding context."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "The bill adds cross-references so that some existing provisions about participating schools apply only to nonpublic schools.",
      "rationale": "Conveys the restriction to nonpublic schools but does not identify § 49-10-1403(d) and § 49-10-1405(a)(7), which are necessary to identify the affected provisions."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "A new section sets rules for parents of medical-condition students. The parent must make sure IEA funds are used only for the approved expenses listed in § 49-10-1403(b).",
      "rationale": "Conveys the parent's duty, the medical-condition scope, and the restriction to the specified approved expenses."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "The department must create and carry out a process to regularly monitor these accounts for compliance.",
      "rationale": "Conveys mandatory creation and implementation of regular monitoring; the preceding context identifies the medical-condition accounts and approved-expense requirements."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The department may suspend or terminate a student's participation if it finds the parent did not comply.",
      "rationale": "Conveys the department's discretionary suspension or termination authority upon a finding of parental noncompliance with the new rules."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "A student who is terminated would be ineligible to take part in the future.",
      "rationale": "Conveys permanent future ineligibility following termination under the new section."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "The act would take effect July 1, 2026.",
      "rationale": "States the effective date exactly."
    }
  ]
}
